'use strict';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bogota',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const state={user:null,csrf:'',cases:[],managers:[],selected:null,current:null,draft:null,formDirty:false,importToken:null,locked:true,loaded:false,pinMode:'desbloquear',policy:null,policyRequired:false,lastActivity:Date.now(),lastHeartbeat:0};
for(const nav of document.querySelectorAll('.sidebar nav,.mobile-nav')){const button=document.createElement('button');button.dataset.view='documents';button.className=nav.classList.contains('mobile-nav')?'':'nav-item';button.innerHTML='<span>▱</span> Documentos';nav.append(button)}
let toastTimer,stream,scanTimer,recognition;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6500)}
async function api(path,options={}){
  const headers={...(options.headers||{})};
  if(options.body&&typeof options.body==='object'&&!(options.body instanceof File)&&!(options.body instanceof Blob)){options.body=JSON.stringify(options.body);headers['Content-Type']='application/json'}
  if(options.method&&options.method!=='GET')headers['X-CSRF-Token']=state.csrf;
  let response;
  try{if(path.includes('/local-'))response=await OfflineVault.route(path,{...options,headers});else response=await fetch('/api'+path,{...options,headers,credentials:'same-origin',cache:'no-store'});$('connection-status').textContent=response.headers.get('X-Offline')?'Sin conexión · Trabajo local protegido':'Conexión disponible'}
  catch(error){response=await OfflineVault.route(path,{...options,headers});$('connection-status').textContent='Sin conexión · Trabajo local protegido'}
  if(!response.ok){let message='No se pudo completar la operación';try{message=(await response.json()).error||message}catch{}if(response.status===401){state.user=null;state.locked=true;$('app').hidden=true;$('login-screen').hidden=false;if($('pin-dialog').open)$('pin-dialog').close()}if(response.status===423)lockApp(false);if(response.status===428)showPrivacy(true);throw new Error(message)}
  return response;
}
async function json(path,options){return(await api(path,options)).json()}
async function download(path,name){try{const response=await api(path),disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename\*=UTF-8''([^;]+)/i);if(match)name=decodeURIComponent(match[1]);const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message)}}
function canLeave(){return !state.formDirty||window.confirm('Hay cambios sin guardar. ¿Quieres salir de este seguimiento?')}
function view(name,force=false){
  if(!force&&!canLeave())return false;
  if(name!=='followup'){state.formDirty=false;stopDictation()}
  ['cases','followup','managers','master','documents'].forEach(v=>$(v+'-view').hidden=v!==name);
  document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));
  if(name==='documents')loadDocuments();
  return true;
}
function status(value){return value===1?'<span class="badge">Activo</span>':value===0?'<span class="badge neutral">Retirado</span>':'<span class="badge pending">Por confirmar</span>'}
function displayName(b){return b.nombres||b.nombre_completo||b.codigo_beneficiario}
function initials(name){return name.split(/\s+/).filter(Boolean).slice(0,2).map(n=>n[0]).join('')}
async function refresh(){
  [state.cases,state.managers]=await Promise.all([json('/beneficiarios'),json('/gestoras')]);
  $('count-all').textContent=state.cases.length;$('count-active').textContent=state.cases.filter(b=>b.activo===1).length;$('count-pending').textContent=state.cases.filter(b=>b.activo===null).length;
  const old=$('filter-manager').value;$('filter-manager').innerHTML='<option value="all">Todas las gestoras</option>'+state.managers.map(g=>`<option value="${esc(g.codigo_gestora)}">${esc(g.nombre)}</option>`).join('');$('filter-manager').value=state.managers.some(g=>g.codigo_gestora===old)?old:'all';
  $('manager-items').innerHTML=state.managers.map(g=>`<tr><td class="code">${esc(g.codigo_gestora)}</td><td>${esc(g.nombre)}</td><td>${status(g.activo)}</td></tr>`).join('');renderList();
  if($('drive-manager'))$('drive-manager').innerHTML=state.managers.filter(g=>g.activo).map(g=>`<option value="${esc(g.codigo_gestora)}">${esc(g.nombre)} · ${esc(g.codigo_gestora)}</option>`).join('');
}
function renderList(){
  const search=$('search').value.trim().toLocaleLowerCase('es'),selected=$('filter-status').value,manager=$('filter-manager').value;
  const rows=state.cases.filter(b=>(`${b.nombre_completo} ${b.nombres} ${b.documento} ${b.codigo_beneficiario} ${b.sim}`).toLocaleLowerCase('es').includes(search)&&(selected==='all'||selected==='pending'&&b.activo===null||String(b.activo)===selected)&&(manager==='all'||b.codigo_gestora===manager));
  $('result-count').textContent=`${rows.length} registros`;
  $('case-items').innerHTML=rows.length?rows.map(b=>`<button class="person-item ${state.selected===b.codigo_beneficiario?'selected':''}" data-case="${esc(b.codigo_beneficiario)}" aria-label="Consultar ${esc(displayName(b))}"><span class="avatar" aria-hidden="true">${esc(initials(displayName(b)))}</span><span class="person-text"><strong>${esc(displayName(b))}</strong><small>${esc(b.codigo_beneficiario)} · ${esc(b.tipo_documento||'Doc.')} ${esc(b.documento)}</small></span><span class="state-mark ${b.activo===1?'active':b.activo===0?'retired':''}" aria-label="${b.activo===1?'Activo':b.activo===0?'Retirado':'Estado por confirmar'}"></span></button>`).join(''):'<div class="empty"><h2>Sin resultados</h2><p>Prueba otro nombre o código. Si aún no hay beneficiarios, usa Cargar maestro.</p></div>';
}
function age(date,at=today()){
  if(!date)return 'Por completar';const birth=new Date(date+'T00:00:00Z'),ref=new Date(at+'T00:00:00Z');let y=ref.getUTCFullYear()-birth.getUTCFullYear(),m=ref.getUTCMonth()-birth.getUTCMonth();if(ref.getUTCDate()<birth.getUTCDate())m--;if(m<0){y--;m+=12}return `${y} años, ${m} meses`;
}
async function selectCase(code){
  try{
    const b=await json('/beneficiarios/'+encodeURIComponent(code));state.current=b;state.selected=code;renderList();
    const datum=(label,value)=>`<div class="datum"><small>${esc(label)}</small><span>${esc(value||'Por completar')}</span></div>`;
    $('case-detail').innerHTML=`<button class="quiet mobile-back" id="mobile-back">← Todos los beneficiarios</button><div class="detail-top"><div class="detail-code"><span class="code">${esc(code)}</span>${status(b.activo)}</div><h2 class="detail-name">${esc(displayName(b))}</h2><p class="muted">Acompañamiento a cargo de ${esc(b.gestora)}</p></div><div class="detail-grid">${datum('Documento',`${b.tipo_documento||''} ${b.documento||''}`)}${datum('Número SIM',b.sim)}${datum('Edad a la fecha',age(b.fecha_nacimiento))}${datum('Ingreso a modalidad',b.fecha_ingreso_modalidad)}${datum('Centro zonal',b.centro_zonal)}${datum('Madre / padre sustituto',b.madre_padre_sustituto)}</div><div class="detail-actions"><button class="primary" id="new-followup" ${b.activo===0?'disabled':''}>+ Nuevo seguimiento</button><button id="case-qr">↓ QR</button></div><div class="history"><div class="section-heading"><h3>SEGUIMIENTOS</h3><span class="code">${b.seguimientos.length} registros</span></div>${b.seguimientos.map(s=>`<div class="history-row"><div>${esc(s.fecha_elaboracion)}<small>${esc(s.nivel_riesgo||'Riesgo pendiente')} · ${esc(s.estado)}</small></div><button data-report="${s.id}" class="quiet">Ver informe →</button></div>`).join('')||'<p class="empty-history">El primer seguimiento comenzará aquí.</p>'}</div>${state.user.rol==='admin'?`<details class="state-editor"><summary>Administrar ingreso o retiro</summary><form id="state-form"><label for="state-value">Estado confirmado</label><select id="state-value"><option value="1">Activo</option><option value="0">Retirado</option></select><label for="state-date">Fecha del cambio</label><input id="state-date" type="date" value="${today()}" required><label for="state-reason">Motivo</label><input id="state-reason" required placeholder="Indica el motivo del cambio"><button type="submit">Confirmar estado</button></form></details>`:''}`;
    document.querySelector('.case-layout').classList.add('detail-open');
    state.gps=null;const residence=document.createElement('details');residence.className='state-editor';const r=b.residencia;
    residence.innerHTML=`<summary>Residencia y ubicación GPS</summary><form id="residence-form"><label for="residence-address">Dirección de residencia</label><input id="residence-address" value="${esc(b.direccion_residencia||r?.direccion||'')}" required maxlength="1000"><label for="residence-city">Municipio</label><input id="residence-city" value="${esc(b.municipio_residencia||r?.municipio||'')}" required maxlength="200"><button id="capture-residence-gps" type="button">Capturar ubicación de la residencia</button><p id="gps-status" class="field-caption">${r?'Último registro: '+esc(r.procedencia)+' · '+esc(r.fecha_captura):'El permiso GPS se solicitará solo al pulsar el botón. También puedes guardar la dirección manualmente.'}</p><label class="consent"><input id="residence-confirm" type="checkbox" required><span>Confirmo que estos datos corresponden a la residencia. Si capturé GPS, estoy en esa ubicación.</span></label><button type="submit">Guardar residencia</button></form>`;$('case-detail').append(residence);
  }catch(e){toast(e.message)}
}
function field(name,label,value='',kind='text',wide=false,voice=false){
  const id='field-'+name;let input;let reference='';
  if(kind==='date'&&value&&!/^\d{4}-\d{2}-\d{2}$/.test(String(value))){reference='<p class="field-caption">Dato de origen por revisar: '+esc(value)+'</p>';value=''}
  if(kind==='textarea')input=`<textarea id="${id}" name="${name}">${esc(value)}</textarea>`;
  else input=`<input id="${id}" name="${name}" type="${kind}" value="${esc(value)}">`;
  return `<div class="${wide?'wide':''}"><label for="${id}">${esc(label)}</label>${input}${reference}${voice?`<div class="voice-row"><button type="button" data-dictate="${id}">◉ Dictar por voz</button></div>`:''}</div>`;
}
function selectField(name,label,options,value='',wide=false){return `<div class="${wide?'wide':''}"><label for="field-${name}">${esc(label)}</label><select id="field-${name}" name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(value??'')===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`}
function startForm(saved=null){
  if(!canLeave())return;const b=state.current,g=saved?.generales||b;state.draft=saved?.estado==='borrador'?saved.id:null;
  state.formRequestId=saved?.solicitud_id||crypto.randomUUID();
  $('followup-person').textContent=displayName(b)+' · '+b.codigo_beneficiario;
  $('form-general').innerHTML=`<h2>Información general</h2><p class="field-caption">Los datos se cargan del maestro. Los ajustes realizados aquí quedan en este informe.</p><div class="form-grid">${field('fecha_elaboracion','Fecha de elaboración',saved?.fecha_elaboracion||today(),'date')}${selectField('nivel_riesgo','Nivel de riesgo',[['','Seleccionar'],['Alto/Emergencia','Alto / Emergencia'],['Media','Media'],['Bajo','Bajo']],saved?.nivel_riesgo||'')}${field('regional','Regional',g.regional||'')}${field('centro_zonal','Centro zonal',g.centro_zonal||'')}${field('operador','Operador',g.operador||'')}${field('modalidad','Modalidad',g.modalidad||'')}${field('escolaridad','Escolaridad',g.escolaridad||'')}${field('autoridad_competente','Autoridad administrativa',g.autoridad_competente||'')}${field('fecha_apertura_pard','Fecha de apertura al PARD',g.fecha_apertura_pard||'','date')}${field('fecha_ingreso_modalidad','Fecha de ingreso a modalidad',g.fecha_ingreso_modalidad||'','date')}${field('motivo_ingreso','Motivo de ingreso',g.motivo_ingreso||'','textarea',true,true)}${field('concepto_evaluacion_integradora','Concepto de evaluación integradora',g.concepto_evaluacion_integradora||'','textarea',true,true)}</div>`;
  state.documentId=saved?.documento_revision_id||null;
  if(state.documentId){const review=document.createElement('label');review.className='consent';review.innerHTML='<input id="document-ack" type="checkbox"><span>Revisé el PDF, el beneficiario vinculado y los datos extraídos antes de registrarlos.</span>';$('form-general').append(review)}
  $('advance-rows').innerHTML='';$('action-rows').innerHTML='';$('person-rows').innerHTML='';
  $('closing-fields').innerHTML=field('conclusiones','Conclusiones y recomendaciones',saved?.conclusiones||'','textarea',true,true)+field('percepcion_beneficiario_red','Percepción del beneficiario, familia o red de apoyo',saved?.percepcion_beneficiario_red||'','textarea',true,true)+field('fecha_envio_autoridad','Fecha de envío a la autoridad administrativa',saved?.fecha_envio_autoridad||'','date');
  (saved?.avances?.length?saved.avances:[{}]).forEach(addAdvance);(saved?.nuevas_atenciones||[]).forEach(addAction);(saved?.participantes?.length?saved.participantes:[{}]).forEach(addPerson);
  $('no-actions').hidden=!!$('action-rows').children.length;
  state.formDirty=false;view('followup',true);step(0);$('form-status').textContent='Revisa la información antes de guardar.';window.scrollTo({top:0,behavior:'instant'});
}
let rowNumber=0;
function repeatRow(container,label,content){const div=document.createElement('div');div.className='repeat-row';div.innerHTML=`<div class="row-heading"><strong>${label}</strong><button type="button" class="remove-row">Quitar fila</button></div><div class="form-grid">${content}</div>`;$(container).append(div);return div}
function addAdvance(a={}){const prefix='a'+(++rowNumber)+'_';repeatRow('advance-rows','Avance',field(prefix+'situacion_abordada','Situación abordada del plan o informe anterior',a.situacion_abordada||'','textarea',true,true)+field(prefix+'atencion_realizada','Atención realizada',a.atencion_realizada||'','textarea',true,true)+field(prefix+'avance_cuantitativo','Descripción cuantitativa de avances',a.avance_cuantitativo||'')+selectField(prefix+'requiere_atenciones_adicionales','¿Requiere atenciones adicionales?',[['','Seleccionar'],['1','Sí'],['0','No']],a.requiere_atenciones_adicionales===true?1:a.requiere_atenciones_adicionales===false?0:a.requiere_atenciones_adicionales??'')+field(prefix+'avance_cualitativo','Descripción cualitativa de avances',a.avance_cualitativo||'','textarea',true,true))}
function addAction(a={}){const prefix='n'+(++rowNumber)+'_';repeatRow('action-rows','Nueva atención',field(prefix+'situacion','Situación por abordar',a.situacion||'','textarea',true,true)+selectField(prefix+'prioridad','Grado de prioridad · GP',[['1','1 · Durante el proceso'],['2','2 · Antes del siguiente informe'],['3','3 · Urgente, 24 a 48 horas']],a.prioridad||1)+selectField(prefix+'nivel_atencion','Nivel de atención · NAT',[['I','I · Individual'],['F','F · Familiar / red de apoyo'],['S','S · Sectores y otros servicios']],a.nivel_atencion||'I')+field(prefix+'resultado_esperado','Resultado esperado',a.resultado_esperado||'','textarea',true,true)+field(prefix+'atencion_necesaria','Atención necesaria',a.atencion_necesaria||'','textarea',true,true)+field(prefix+'responsable','Responsable',a.responsable||'')+field(prefix+'fecha_limite','Fecha límite',a.fecha_limite||'','date'));$('no-actions').hidden=true}
function addPerson(p={}){const prefix='p'+(++rowNumber)+'_';repeatRow('person-rows','Participante',field(prefix+'rol_en_caso','Rol en el caso',p.rol_en_caso||'')+field(prefix+'nombre','Nombres y apellidos',p.nombre||'')+field(prefix+'profesion','Profesión o rol profesional',p.profesion||''))}
function step(n){document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=Number(p.dataset.panel)!==n);document.querySelectorAll('[data-step]').forEach(b=>b.setAttribute('aria-selected',String(Number(b.dataset.step)===n)))}
function readRows(container){return [...$(container).children].map(row=>{const value={};row.querySelectorAll('[name]').forEach(el=>{const name=el.name.replace(/^[anp]\d+_/,'');value[name]=el.value;if(name==='prioridad')value[name]=Number(el.value);if(name==='requiere_atenciones_adicionales')value[name]=el.value===''?null:el.value==='1'});return value})}
async function saveFollowup(finalize){
  stopDictation();const value=name=>$('field-'+name).value;
  const body={fecha_elaboracion:value('fecha_elaboracion'),nivel_riesgo:value('nivel_riesgo'),estado:finalize?'finalizado':'borrador',conclusiones:value('conclusiones'),percepcion_beneficiario_red:value('percepcion_beneficiario_red'),fecha_envio_autoridad:value('fecha_envio_autoridad'),generales:{},avances:readRows('advance-rows'),nuevas_atenciones:readRows('action-rows'),participantes:readRows('person-rows')};
  body.solicitud_id=state.formRequestId;
  ['regional','centro_zonal','operador','modalidad','escolaridad','autoridad_competente','fecha_apertura_pard','fecha_ingreso_modalidad','motivo_ingreso','concepto_evaluacion_integradora'].forEach(k=>body.generales[k]=value(k));
  if(state.documentId){body.documento_revision_id=state.documentId;body.documento_revisado=!!$('document-ack')?.checked}
  const buttons=$('followup-form').querySelectorAll('button');buttons.forEach(b=>b.disabled=true);$('form-status').textContent='Guardando…';
  try{const path=state.draft?'/seguimientos/'+state.draft:'/beneficiarios/'+state.selected+'/seguimientos';const result=await json(path,{method:state.draft?'PUT':'POST',body});state.formDirty=false;await refresh();await selectCase(state.selected);view('cases',true);toast(result.sin_conexion?'Guardado en este dispositivo. Pendiente de sincronizar cuando vuelva la conexión.':finalize?'Seguimiento finalizado. Ya puedes descargar los entregables.':'Borrador guardado. Puedes continuarlo desde la ficha.');await showReport(result.id)}catch(e){$('form-status').textContent=e.message;toast(e.message)}finally{buttons.forEach(b=>b.disabled=false)}
}
async function showReport(id){
  try{const report=await json('/seguimientos/'+id);state.report=report;
    const lines=[`Riesgo: ${report.nivel_riesgo||'Pendiente'}`,...report.avances.map((a,i)=>`Avance ${i+1}\n${a.situacion_abordada}\nAtención: ${a.atencion_realizada}\nCuantitativo: ${a.avance_cuantitativo}\nCualitativo: ${a.avance_cualitativo}`),...report.nuevas_atenciones.map((a,i)=>`Nueva atención ${i+1} · GP ${a.prioridad} · NAT ${a.nivel_atencion}\n${a.situacion}\nResultado: ${a.resultado_esperado}\nAtención: ${a.atencion_necesaria}\nResponsable: ${a.responsable}\nFecha límite: ${a.fecha_limite||'Pendiente'}`),`Conclusiones\n${report.conclusiones||'Pendiente'}`,`Percepción del beneficiario / red\n${report.percepcion_beneficiario_red||'Pendiente'}`];
    $('report-content').innerHTML=`<p><span class="code">${esc(report.codigo_beneficiario)}</span> · ${esc(report.fecha_elaboracion)}</p><p>${esc(report.generales.nombres||report.generales.nombre_completo)}</p><span class="badge neutral">${esc(report.estado)}</span>${report.sin_conexion?'<p class="policy-draft">Guardado de forma protegida en este dispositivo. Pendiente de sincronizar; los entregables se generan después de sincronizar.</p>':'<div class="export-buttons">'+['pdf','csv','xlsx'].map(fmt=>`<button data-export="${fmt}" data-id="${id}">↓ ${fmt==='xlsx'?'Excel':fmt.toUpperCase()}</button>`).join('')+'</div>'}${report.estado==='borrador'?'<button id="continue-draft" class="primary full">Continuar borrador</button>':''}<details><summary>Consultar contenido del seguimiento</summary><pre>${esc(lines.join('\n\n'))}</pre></details>`;
    $('report-dialog').showModal();
  }catch(e){toast(e.message)}
}
function stopCamera(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}clearTimeout(scanTimer);$('qr-video').hidden=true;$('qr-video').srcObject=null}
function closeQr(){stopCamera();$('qr-dialog').close()}
async function resolveQr(raw){
  const code=raw.trim().replace(/^PLAN-CASO:/,'').toUpperCase();if(!/^BEN-\d{6}$/.test(code)){toast('El código debe tener el formato BEN-000001.');return}
  try{await json('/beneficiarios/'+code);closeQr();view('cases');await selectCase(code)}catch(e){toast(e.message)}
}
async function startCamera(){
  if(!('BarcodeDetector'in window)){$('qr-message').textContent='Este navegador no ofrece lectura QR integrada. Usa un navegador compatible o escribe el código que aparece debajo del QR.';return}
  if(!navigator.mediaDevices?.getUserMedia){$('qr-message').textContent='La cámara necesita una conexión HTTPS y un navegador compatible.';return}
  try{const formats=await BarcodeDetector.getSupportedFormats();if(!formats.includes('qr_code'))throw new Error('Este navegador no admite lectura QR. Escribe el código.');
    stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});const video=$('qr-video');video.srcObject=stream;video.hidden=false;await video.play();$('qr-message').textContent='Apunta la cámara al QR del beneficiario.';const detector=new BarcodeDetector({formats:['qr_code']});
    async function scan(){if(!stream)return;try{const codes=await detector.detect(video);if(codes.length){await resolveQr(codes[0].rawValue);return}}catch{}scanTimer=setTimeout(scan,400)}scan();
  }catch(e){stopCamera();$('qr-message').textContent=e.message||'No fue posible activar la cámara. Puedes escribir el código.'}
}
function stopDictation(){if(recognition){recognition.stop();recognition=null}document.querySelectorAll('.listening').forEach(b=>{b.classList.remove('listening');b.textContent='◉ Dictar por voz'})}
function dictate(button){
  if(button.classList.contains('listening')){stopDictation();return}stopDictation();
  const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!Speech){toast('El dictado no está disponible en este navegador. Puedes usar el micrófono del teclado del móvil.');return}
  const input=$(button.dataset.dictate);recognition=new Speech();recognition.lang='es-CO';recognition.continuous=true;recognition.interimResults=false;
  button.classList.add('listening');button.textContent='■ Detener dictado';
  recognition.onresult=event=>{let text='';for(let i=event.resultIndex;i<event.results.length;i++)if(event.results[i].isFinal)text+=event.results[i][0].transcript+' ';input.value+=(input.value?' ':'')+text.trim();state.formDirty=true};
  recognition.onerror=event=>{toast('No se pudo completar el dictado ('+event.error+'). Revisa permisos o usa el teclado.');stopDictation()};
  recognition.onend=()=>{button.classList.remove('listening');button.textContent='◉ Dictar por voz';recognition=null};
  try{recognition.start();toast('Dictado activado. Revisa el texto antes de guardar. El servicio de voz depende del navegador.')}catch(e){stopDictation();toast(e.message)}
}
async function boot(){
  try{state.user=await json('/me');state.csrf=state.user.csrf;$('login-screen').hidden=true;$('user-label').textContent=state.user.usuario;document.querySelectorAll('.admin-only').forEach(el=>el.hidden=state.user.rol!=='admin');if(!state.user.bloqueada)await json('/bloquear',{method:'POST'});lockApp(false)}catch(e){if(state.user)toast(e.message)}
}

