$('followup-form').onsubmit=e=>{e.preventDefault();saveFollowup(true)};$('save-draft').onclick=()=>saveFollowup(false);
$('manager-form').onsubmit=async e=>{e.preventDefault();try{await json('/gestoras',{method:'POST',body:{nombre:$('manager-name').value}});$('manager-name').value='';await refresh();toast('Gestora registrada con su nuevo código.')}catch(err){toast(err.message)}};
$('download-master').onclick=()=>download('/maestro.xlsx','maestro_beneficiarios.xlsx');
$('import-form').onsubmit=async e=>{e.preventDefault();const file=$('master-file').files[0];if(!file)return;if(file.size>8_000_000){toast('El archivo supera 8 MB.');return}const button=e.submitter;button.disabled=true;state.importToken=null;try{const result=await json('/importar/revisar',{method:'POST',body:file,headers:{'Content-Type':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}});state.importToken=result.token;$('import-result').innerHTML=`<div class="import-summary"><h2>Revisión del maestro</h2><p>${result.altas} altas · ${result.actualizaciones} actualizaciones · ${result.errores.length} errores</p>${result.errores.length?'<ul class="error">'+result.errores.map(m=>'<li>'+esc(m)+'</li>').join('')+'</ul>':''}${result.avisos.length?'<ul>'+result.avisos.map(m=>'<li>'+esc(m)+'</li>').join('')+'</ul>':''}${result.cambios.length?'<details><summary>Ver cambios por beneficiario</summary><ul>'+result.cambios.map(c=>`<li>${esc(c.codigo)} · ${esc(c.tipo)} · ${esc(c.campos.join(', '))}</li>`).join('')+'</ul></details>':''}${result.token&&result.cambios.length?'<button id="apply-import" class="primary">Confirmar y aplicar cambios</button>':''}</div>`}catch(err){toast(err.message)}finally{button.disabled=false}};
$('import-result').onclick=async e=>{if(e.target.id!=='apply-import')return;e.target.disabled=true;try{const result=await json('/importar/aplicar',{method:'POST',body:{token:state.importToken}});state.importToken=null;$('import-result').innerHTML='';$('master-file').value='';await refresh();if(state.selected)await selectCase(state.selected);toast(result.aplicados+' cambios aplicados al maestro.')}catch(err){e.target.disabled=false;toast(err.message)}};
$('open-qr').onclick=()=>{if(!canLeave())return;$('qr-message').textContent='La lectura con cámara requiere HTTPS y compatibilidad del navegador.';$('qr-dialog').showModal()};$('close-qr').onclick=closeQr;$('qr-dialog').addEventListener('cancel',stopCamera);$('start-camera').onclick=startCamera;$('qr-form').onsubmit=e=>{e.preventDefault();resolveQr($('qr-code').value)};
$('close-report').onclick=()=>$('report-dialog').close();$('report-content').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.export)download('/seguimientos/'+b.dataset.id+'.'+b.dataset.export,'seguimiento_'+b.dataset.id+'.'+b.dataset.export);if(b.id==='continue-draft'){$('report-dialog').close();startForm(state.report)}};
window.addEventListener('beforeunload',event=>{stopCamera();stopDictation();if(state.formDirty){event.preventDefault();event.returnValue=''}});
document.querySelectorAll('[data-step]').forEach(b=>{const n=b.dataset.step;b.id='step-'+n;b.setAttribute('aria-controls','panel-'+n);const panel=document.querySelector('[data-panel="'+n+'"]');if(panel){panel.id=n==='0'?'form-general':'panel-'+n;b.setAttribute('aria-controls',panel.id);panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',b.id)}});
$('followup-tabs').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const current=Number(event.target.dataset.step);if(Number.isNaN(current))return;event.preventDefault();const n=event.key==='Home'?0:event.key==='End'?3:(current+(event.key==='ArrowRight'?1:3))%4;step(n);document.querySelector('[data-step="'+n+'"]').focus()});
boot();
